lib_code='''def sections(grid):
    """Split the grid at a full uniform separator row/column whose color appears nowhere else; return the section subgrids."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    cnt = Counter(v for row in grid for v in row)
    def uniform_line(i):
        return len(set(grid[i])) == 1
    def uniform_col(j):
        return len({grid[i][j] for i in range(h)}) == 1
    def color_unique(v):
        return cnt[v] == (w if isinstance(v, int) else 0)
    rows = [i for i in range(h) if uniform_line(i) and cnt[grid[i][0]] == w]
    cols = [j for j in range(w) if uniform_col(j) and cnt[grid[0][j]] == h]
    def split_row():
        groups, start = [], 0
        for r in rows + [h]:
            if r > start:
                groups.append([row[:] for row in grid[start:r]])
            start = r + 1
        return groups
    def split_col():
        groups, start = [], 0
        for c in cols + [w]:
            if c > start:
                groups.append([[grid[i][j] for j in range(start, c)] for i in range(h)])
            start = c + 1
        return groups
    return split_row() if rows else split_col()

def overlay(a, b, color):
    """Color where both grids are nonzero, else 0; grids must be the same size."""
    return [[color if a[i][j] != 0 and b[i][j] != 0 else 0 for j in range(len(a[0]))] for i in range(len(a))]
'''
